<?php
require_once __DIR__.'/../config/auth.php'; require_admin(); require_once __DIR__.'/../includes/loyalty.php';
require_once __DIR__.'/../includes/notifications.php';
$pdo=db(); $pageTitle='Poin Member & Reward'; $error='';
if($pdo){try{loyalty_ensure_tables($pdo);}catch(Throwable $e){$error='Tabel loyalty belum dapat dibuat: '.$e->getMessage();}}
if(empty($_SESSION['loyalty_csrf']))$_SESSION['loyalty_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['loyalty_csrf'];
if($_SERVER['REQUEST_METHOD']==='POST' && $pdo){
 if(!hash_equals($csrf,$_POST['csrf']??''))$error='Permintaan tidak valid.';
 else try{
  $action=$_POST['action']??'';
  if($action==='settings'){
   $per=max(1,(float)$_POST['points_per_amount']);$min=max(0,(float)$_POST['points_per_order_min']);$s=$pdo->prepare('UPDATE loyalty_settings SET points_per_amount=?, points_per_order_min=? WHERE id=1');$s->execute([$per,$min]);admin_flash('success','Aturan poin berhasil disimpan.');header('Location: '.page_url('admin/loyalty.php'));exit;
  }
  if($action==='reward'){
   $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$cost=max(1,(int)$_POST['points_cost']);$type=$_POST['discount_type']==='percent'?'percent':'fixed';$value=max(0,(float)$_POST['discount_value']);$min=max(0,(float)$_POST['min_order']);$max=trim($_POST['max_discount']??'');$max=$max===''?null:max(0,(float)$max);$days=max(1,(int)$_POST['validity_days']);$quota=trim($_POST['quota']??'');$quota=$quota===''?null:max(1,(int)$quota);$status=$_POST['status']==='inactive'?'inactive':'active';if($name===''||$value<=0)throw new RuntimeException('Nama reward dan nilai diskon wajib diisi.');
   if($id){$s=$pdo->prepare('UPDATE loyalty_rewards SET name=?,points_cost=?,discount_type=?,discount_value=?,min_order=?,max_discount=?,validity_days=?,quota=?,status=? WHERE id=?');$s->execute([$name,$cost,$type,$value,$min,$max,$days,$quota,$status,$id]);$m='Reward berhasil diperbarui.';}else{$s=$pdo->prepare('INSERT INTO loyalty_rewards(name,points_cost,discount_type,discount_value,min_order,max_discount,validity_days,quota,status) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$name,$cost,$type,$value,$min,$max,$days,$quota,$status]);$m='Reward berhasil dibuat.'; if($status==='active'){ try { member_notification_broadcast($pdo,'reward','Reward Member baru tersedia 🎁',$name.' tersedia. Tukarkan poin Anda untuk mendapatkan reward ini.',page_url('poin-member.php')); } catch(Throwable $e) {} }}admin_flash('success',$m);header('Location: '.page_url('admin/loyalty.php'));exit;
  }
  if($action==='delete'){ $id=(int)$_POST['id'];$s=$pdo->prepare('DELETE FROM loyalty_rewards WHERE id=?');$s->execute([$id]);admin_flash('success','Reward berhasil dihapus.');header('Location: '.page_url('admin/loyalty.php'));exit; }
  if($action==='adjust'){
   $cid=(int)$_POST['customer_id'];$points=(int)$_POST['points'];$desc=trim($_POST['description']??'Penyesuaian poin oleh Admin');if($cid<=0||$points===0)throw new RuntimeException('Member dan jumlah poin wajib diisi.');$exists=$pdo->prepare('SELECT id FROM customers WHERE id=? AND is_verified=1');$exists->execute([$cid]);if(!$exists->fetchColumn())throw new RuntimeException('Member tidak ditemukan.');$bal=loyalty_balance($pdo,$cid);if($bal+$points<0)throw new RuntimeException('Poin tidak boleh menjadi negatif.');$s=$pdo->prepare('INSERT INTO loyalty_transactions(customer_id,type,points,balance_after,description) VALUES(?,?,?,?,?)');$s->execute([$cid,'adjust',$points,$bal+$points,$desc]); try { $nm=$pdo->prepare('SELECT name FROM customers WHERE id=?');$nm->execute([$cid]);$memberName=(string)$nm->fetchColumn(); if($points>0){ member_notification_add($pdo,$cid,'bonus','Bonus poin masuk 🎉','Halo '.$memberName.', Anda mendapatkan bonus '.$points.' poin. '.($desc!==''?$desc:'Terima kasih sudah menjadi Member Rosa Indah Printing.').' ',page_url('poin-member.php')); } else { member_notification_add($pdo,$cid,'points','Penyesuaian poin Member','Saldo poin Anda disesuaikan sebesar '.$points.' poin. '.($desc!==''?$desc:''),page_url('poin-member.php')); } } catch(Throwable $e) {} admin_flash('success','Poin Member berhasil disesuaikan.');header('Location: '.page_url('admin/loyalty.php'));exit;
  }
 }catch(Throwable $e){$error=$e->getMessage();}
}
$settings=$pdo?loyalty_settings($pdo):['points_per_amount'=>10000,'points_per_order_min'=>0];$rewards=$pdo?$pdo->query('SELECT * FROM loyalty_rewards ORDER BY points_cost ASC,id DESC')->fetchAll():[];$members=$pdo?$pdo->query('SELECT id,name,phone FROM customers WHERE is_verified=1 ORDER BY name ASC')->fetchAll():[];
$memberBalances=[];if($pdo){$q=$pdo->query('SELECT c.id,c.name,c.phone,COALESCE(SUM(t.points),0) points FROM customers c LEFT JOIN loyalty_transactions t ON t.customer_id=c.id WHERE c.is_verified=1 GROUP BY c.id ORDER BY points DESC,name ASC LIMIT 100');$memberBalances=$q->fetchAll();}
$editId=(int)($_GET['edit']??0);$edit=null;if($editId&&$pdo){$q=$pdo->prepare('SELECT * FROM loyalty_rewards WHERE id=?');$q->execute([$editId]);$edit=$q->fetch()?:null;}
require_once __DIR__.'/_header.php';
function le($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><div class="admin-title"><div><h1>Poin Member & Reward</h1><p style="color:#777;margin:7px 0 0">Kelola aturan Loyalty Member, reward voucher, dan penyesuaian poin.</p></div></div><?php if($error):?><div class="admin-alert error"><?php echo le($error);?></div><?php endif;?><div class="admin-grid-2"><section class="admin-card"><h2>⚙️ Aturan Perolehan Poin</h2><p style="color:#777;font-size:13px">Poin diberikan otomatis satu kali ketika pesanan Member berubah menjadi <strong>Selesai</strong>.</p><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?php echo le($csrf);?>"><input type="hidden" name="action" value="settings"><div class="admin-field"><label>Setiap belanja berapa Rupiah = 1 poin?</label><input type="number" name="points_per_amount" min="1" value="<?php echo le($settings['points_per_amount']);?>"></div><div class="admin-field"><label>Minimum belanja per pesanan (opsional)</label><input type="number" name="points_per_order_min" min="0" value="<?php echo le($settings['points_per_order_min']);?>"></div><button class="admin-btn" type="submit"><i class="bi bi-save"></i> Simpan Aturan Poin</button></form></section><section class="admin-card"><h2>➕ Penyesuaian Poin</h2><p style="color:#777;font-size:13px">Gunakan bila Admin ingin memberi bonus atau mengoreksi poin.</p><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?php echo le($csrf);?>"><input type="hidden" name="action" value="adjust"><div class="admin-field"><label>Member</label><select name="customer_id" required><option value="">Pilih Member</option><?php foreach($members as $m):?><option value="<?php echo (int)$m['id'];?>"><?php echo le($m['name']);?> — <?php echo le($m['phone']);?></option><?php endforeach;?></select></div><div class="admin-grid-2"><div class="admin-field"><label>Jumlah poin (+/-)</label><input type="number" name="points" required placeholder="Contoh: 50 atau -50"></div><div class="admin-field"><label>Keterangan</label><input name="description" placeholder="Bonus promo Member"></div></div><button class="admin-btn" type="submit">Simpan Penyesuaian</button></form></section></div><section class="admin-card" style="margin-top:18px"><div class="admin-title" style="margin-bottom:15px"><div><h2 style="margin:0">🎁 <?php echo $edit?'Edit Reward':'Buat Reward';?></h2></div><?php if($edit):?><a class="admin-btn secondary" href="<?php echo page_url('admin/loyalty.php');?>">Batal Edit</a><?php endif;?></div><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?php echo le($csrf);?>"><input type="hidden" name="action" value="reward"><input type="hidden" name="id" value="<?php echo (int)($edit['id']??0);?>"><div class="admin-grid-2"><div class="admin-field"><label>Nama Reward *</label><input name="name" required value="<?php echo le($edit['name']??'Voucher Rp10.000');?>"></div><div class="admin-field"><label>Biaya Poin *</label><input type="number" name="points_cost" min="1" required value="<?php echo le($edit['points_cost']??100);?>"></div></div><div class="admin-grid-2"><div class="admin-field"><label>Jenis Diskon</label><select name="discount_type"><option value="fixed" <?php echo (($edit['discount_type']??'fixed')==='fixed')?'selected':'';?>>Nominal Rupiah</option><option value="percent" <?php echo (($edit['discount_type']??'fixed')==='percent')?'selected':'';?>>Persentase</option></select></div><div class="admin-field"><label>Nilai Diskon *</label><input type="number" name="discount_value" min="1" required value="<?php echo le($edit['discount_value']??10000);?>"></div></div><div class="admin-grid-2"><div class="admin-field"><label>Minimum Belanja</label><input type="number" name="min_order" min="0" value="<?php echo le($edit['min_order']??0);?>"></div><div class="admin-field"><label>Maksimal Diskon (opsional)</label><input type="number" name="max_discount" min="0" value="<?php echo le($edit['max_discount']??'');?>"></div></div><div class="admin-grid-2"><div class="admin-field"><label>Masa berlaku voucher (hari)</label><input type="number" name="validity_days" min="1" value="<?php echo le($edit['validity_days']??30);?>"></div><div class="admin-field"><label>Kuota penukaran (opsional)</label><input type="number" name="quota" min="1" value="<?php echo le($edit['quota']??'');?>"></div></div><div class="admin-grid-2"><div class="admin-field"><label>Status</label><select name="status"><option value="active" <?php echo (($edit['status']??'active')==='active')?'selected':'';?>>Aktif</option><option value="inactive" <?php echo (($edit['status']??'active')==='inactive')?'selected':'';?>>Nonaktif</option></select></div><div></div></div><button class="admin-btn" type="submit"><i class="bi bi-save"></i> <?php echo $edit?'Simpan Perubahan':'Buat Reward';?></button></form></section><section class="admin-card" style="margin-top:18px;overflow:auto"><h2>Daftar Reward</h2><table class="admin-table" style="min-width:850px"><thead><tr><th>Reward</th><th>Biaya</th><th>Diskon</th><th>Kuota</th><th>Ditukar</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if(!$rewards):?><tr><td colspan="7">Belum ada reward.</td></tr><?php else:foreach($rewards as $r):?><tr><td><strong><?php echo le($r['name']);?></strong><small style="display:block;color:#888">Berlaku <?php echo (int)$r['validity_days'];?> hari</small></td><td><?php echo number_format((int)$r['points_cost'],0,',','.');?> poin</td><td><?php echo $r['discount_type']==='fixed'?'Rp'.number_format((float)$r['discount_value'],0,',','.'):number_format((float)$r['discount_value'],0,',','.').'%';?></td><td><?php echo $r['quota']===null?'∞':(int)$r['quota'];?></td><td><?php echo (int)$r['redeemed_count'];?></td><td><?php echo le($r['status']);?></td><td><a class="admin-btn secondary" href="<?php echo page_url('admin/loyalty.php?edit='.(int)$r['id']);?>">Edit</a> <form method="post" style="display:inline" onsubmit="return confirm('Hapus reward ini?')"><input type="hidden" name="csrf" value="<?php echo le($csrf);?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?php echo (int)$r['id'];?>"><button class="admin-btn danger" type="submit">Hapus</button></form></td></tr><?php endforeach;endif;?></tbody></table></section><section class="admin-card" style="margin-top:18px;overflow:auto"><h2>Saldo Poin Member</h2><table class="admin-table" style="min-width:650px"><thead><tr><th>Member</th><th>WhatsApp</th><th>Saldo Poin</th></tr></thead><tbody><?php foreach($memberBalances as $m):?><tr><td><strong><?php echo le($m['name']);?></strong></td><td><?php echo le($m['phone']);?></td><td style="color:#d64a8a;font-weight:800"><?php echo number_format((int)$m['points'],0,',','.');?> poin</td></tr><?php endforeach;?></tbody></table></section><style>.admin-card h2{color:#18243a;margin:0 0 8px}.admin-card small{font-size:11px}</style><?php require __DIR__.'/_footer.php';?>
